"""
Logger instance
"""
from pyjab.common.logger import Logger, logging
from io import StringIO

_loggers = {}  # Dictionary to store loggers by name

def get_logger(name="default", level=Logger.LOGGER_INFO):
    if name not in _loggers:  # Check if a logger with the given name already exists
        _loggers[name] = Logger(name, level)  # Create and store the logger
    return _loggers[name]  # Return the logger

logger = get_logger("test")

log_buffer = StringIO()
buffer_handler = logging.StreamHandler(log_buffer)
logger.log.addHandler(buffer_handler)

def mLog(msg, end = "\n"):
    """Log info message every other line"""
    logger.info(msg + end)

def get_logs():
    """Fetch logs from the in-memory buffer."""
    logs = log_buffer.getvalue()  # Get all logs from the buffer
    log_buffer.seek(0)  # Reset the buffer pointer
    log_buffer.truncate(0)  # Clear the buffer
    return logs